#include "7047c02a1d890cbc_item_equip_slots.hpp"
namespace recovered_item_equip_slots{U slot(U self,U mask){switch(mask){case 1:return self+4;case 2:return self+8;case 4:return self+12;case 8:return self+16;case 16:return self+20;case 32:return self+24;case 64:return self+28;case 128:return self+32;case 256:return self+36;case 512:return self+40;case 1024:return self+44;case 16384:return self+48;case 32768:return self+52;case 65536:return self+56;case 131072:return self+60;default:return 0;}}
U equipped(U self,U mask,Ports&p){U a=slot(self,mask);return a?p.item(p.read(a)):0;}
U other(U self,U item,U out,U mode,U messages,Ports&p){if(!p.required_feats(self,item,p.read(out))){if(mode==1&&messages==1)p.signal(self,0x77);return 0;}if(equipped(p.read(self+0xa2c),p.read(out),p)){if(mode==1&&messages==1)p.signal(self,0x7b);return 2;}return 1;}
U weapon(U self,U item,U out,U,U,Ports&p){U mask=p.read(out);if(mask!=16&&mask!=32)return 0;U right=equipped(p.read(self+0xa2c),16,p),left=equipped(p.read(self+0xa2c),32,p);U rightRule=0;if(right)rightRule=p.rule(p.read(right+12));if(left)(void)p.rule(p.read(left+12));if(!item)return 0;U rule=p.rule(p.read(item+12));if(!right){if(left)return 0;if(p.read(out)==32)p.write(out,16);return 1;}U type=p.byte(rule+8);bool two=type==3||type==5||type==6;if(two){p.write(out,16);return 3;}bool ranged=p.byte(rule+0x1a)!=0,oldRanged=p.byte(rightRule+0x1a)!=0;if(left){if(ranged==oldRanged)return 2;p.write(out,16);return 3;}if(ranged==oldRanged){U oldType=p.byte(rightRule+8);if(oldType==1||oldType==2||oldType==4)return p.read(out)==32?1:2;}p.write(out,16);return 2;}}
